import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  ssl: { rejectUnauthorized: false }
});

// Middleware: parse tenant from JWT (simplified)
function extractTenant(req, res, next) {
  const token = req.headers['x-tenant-token'];
  if (!token) return res.status(401).json({ error: 'missing token' });
  // In production this would verify JWT signature
  try {
    const payload = JSON.parse(Buffer.from(token.split('.')[1], 'base64').toString());
    req.tenantId = payload.tenant_id;
    req.userId = payload.sub;
    next();
  } catch (e) {
    return res.status(401).json({ error: 'invalid token' });
  }
}

// Search endpoint with dynamic filtering
app.get('/api/v2/assets/search', extractTenant, async (req, res) => {
  try {
    const { category, tag, sort_by, order } = req.query;

    // Base query with tenant isolation
    let query = `SELECT id, name, category, tags, created_at 
                 FROM assets WHERE tenant_id = $1`;
    const params = [req.tenantId];
    let paramIdx = 2;

    // Category filter - parameterized
    if (category) {
      query += ` AND category = $${paramIdx}`;
      params.push(category);
      paramIdx++;
    }

    // Tag filter - parameterized  
    if (tag) {
      query += ` AND $${paramIdx} = ANY(tags)`;
      params.push(tag);
      paramIdx++;
    }

    // Sort - VULNERABLE: direct interpolation of sort column and order
    const allowedOrders = ['ASC', 'DESC'];
    const sanitizedOrder = allowedOrders.includes(order?.toUpperCase()) ? order.toUpperCase() : 'ASC';

    if (sort_by) {
      // Developer assumed sort_by would be validated client-side
      query += ` ORDER BY ${sort_by} ${sanitizedOrder}`;
    } else {
      query += ` ORDER BY created_at DESC`;
    }

    query += ` LIMIT 100`;

    const result = await pool.query(query, params);

    // Log access for audit
    console.log(JSON.stringify({
      event: 'asset_search',
      tenant: req.tenantId,
      user: req.userId,
      filters: { category, tag, sort_by, order },
      resultCount: result.rows.length
    }));

    return res.json({ assets: result.rows });
  } catch (err) {
    console.error('Search failed:', err.message);
    return res.status(500).json({ error: 'internal error' });
  }
});

// Bulk update endpoint
app.post('/api/v2/assets/bulk-tag', extractTenant, async (req, res) => {
  const { asset_ids, new_tag } = req.body;
  if (!Array.isArray(asset_ids) || !new_tag) {
    return res.status(400).json({ error: 'invalid payload' });
  }

  const client = await pool.connect();
  try {
    await client.query('BEGIN');
    for (const id of asset_ids) {
      await client.query(
        'UPDATE assets SET tags = array_append(tags, $1) WHERE id = $2 AND tenant_id = $3',
        [new_tag, id, req.tenantId]
      );
    }
    await client.query('COMMIT');
    return res.json({ updated: asset_ids.length });
  } catch (err) {
    await client.query('ROLLBACK');
    return res.status(500).json({ error: 'bulk update failed' });
  } finally {
    client.release();
  }
});

app.listen(3000, () => console.log('Asset service listening on :3000'));
